-- Adds kieró Refining Enzyme Cleanser and kieró Airy Sun Stick SPF 50+ to the
-- live catalog, and moves the LOLA pads' subscription complaint out of its
-- safety note (it's a user con, already covered in the community review).
-- Rows extracted from the regenerated supabase/seed/product_catalog.sql
-- (npm run catalog:export). Idempotent: safe to re-run. Run it once in the
-- Supabase SQL editor.

insert into public.product_catalog (id, name, brand, category, product_type, summary, price, image, url, tags, health_functions, where_to_buy, where_to_buy_in_stock, safety, doctor_opinion, community_review, effectiveness, clinician_opinion_source, clinician_attribution, source, internal, requires_prescription, user_rating, is_active, extra)
values
  ('p-kiero-refining-enzyme-cleanser', 'Refining Enzyme Cleanser', 'kieró', 'skincare', 'physical', 'A powder face cleanser that turns into a creamy foam with water, made with papaya enzymes (papain), beta-glucan, and chia seed extract. kieró positions it as a gentle daily enzyme exfoliant that removes impurities and excess oil without drying and refines skin texture. It is step 1 of kieró''s 5-step routine, which blends Korean-beauty formulation with Latin American botanicals.', '$11.99 for 50 g (1.76 oz)', 'https://us.kieroskincare.com/cdn/shop/files/kiero-_-05_9dcbb676-03a3-45a9-bb4e-ae5dd1708f23.jpg', 'https://us.kieroskincare.com/products/refining-enzyme-cleanser', '["skin","cleanser","exfoliation","vegan","fragrance-free"]'::jsonb, '["skin-hair"]'::jsonb, '["kieró"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Cosmetic face cleanser; not an FDA-cleared drug or medical device. kieró states its products are vegan and cruelty-free and use EWG Green-graded ingredients; ayna did not independently verify those claims.","materials":"Water-activated powder (50 g / 1.76 oz). Cleansing comes mainly from mild synthetic surfactants: sodium cocoyl isethionate, sodium methyl cocoyl taurate, and sodium lauroyl glutamate. It also contains potassium laurate, which is a true soap. The enzyme is papain. Supporting ingredients are allantoin, glycerin, beta-glucan, and chia (Salvia hispanica) seed extract. CI 77499 is black iron oxide, a colorant. No added fragrance, essential oils, or sulfates appear in the published ingredient list.","recalls":"No recalls found.","sideEffects":"Papain is a protein-digesting enzyme and a known allergen: people have become sensitized to it at work and through a papain contact-lens solution. Anyone with a papaya, papain, kiwi, or fig allergy should avoid it or patch test first. Any exfoliant can cause redness or irritation if overused, especially alongside retinoids, retinol, or benzoyl peroxide. Full warnings are listed below.","opinionAlerts":"Allergy note: contains papain (papaya enzyme), a known allergen. Avoid it if you''re allergic to papaya, kiwi, or fig, or patch test first. Benefit claims (refined texture, radiance, barrier support) come from kieró, and no independent clinical study of the finished product was found."}'::jsonb, 'kieró positions this as a gentle daily enzyme cleanser. Papaya enzymes exfoliate, beta-glucan hydrates and soothes, and chia seed supports the skin barrier, and the powder foams up to remove oil and impurities without drying, per the brand''s own site.

The cleansing base is a reasonable choice for gentleness. Its main surfactant, sodium cocoyl isethionate, has been shown in lab and human studies to be milder on the skin barrier than soap or sodium lauryl sulfate. That is the basis of "syndet" cleansers dermatologists often recommend for dry or sensitive skin. The formula does also contain potassium laurate, a true soap, so it is not entirely soap-free.

Papain, the papaya enzyme, is an established exfoliant. It breaks down keratin and other skin proteins, which mimics the skin''s natural shedding. A 2021 review found only a handful of studies on enzyme exfoliation and few clinical trials, though the results that exist are positive. A cleanser also stays on the skin for under a minute, so its exfoliating effect is likely mild. The trade-off is that papain is a recognized allergen. Studies show it can loosen the proteins that hold skin cells together and trigger sensitization through the skin. Anyone with a papaya-family allergy should be cautious.

Beta-glucan has real clinical evidence. In controlled studies, topical beta-glucan improved skin hydration and reduced irritation, including in atopic dermatitis and after laser treatment. Chia seed oil improved hydration and barrier function in a small 8-week study of people with dry, itchy skin. That study used a leave-on 4% oil formula, though, not a rinse-off extract. Allantoin is a well-documented soothing and mildly keratolytic skin-protectant ingredient.

The American Academy of Dermatology advises people with dry, sensitive, or acne-prone skin to choose gentle exfoliation and to moisturize afterward. It also warns against exfoliating while using retinoids or benzoyl peroxide, or on broken or sunburned skin. No independent clinical study of this specific product was found.', 'kieró''s US site shows 251 customer reviews, and 233 of them (93%) are five stars. Most reviews are in Spanish and describe skin feeling very clean, soft, and hydrated, for example: "Muy recomendable, te deja la piel suave e hidratada" ("Highly recommend, it leaves your skin soft and hydrated"). These are reviews on the brand''s own site; no independent review data was found at time of writing.', 'Cleanses with mild syndet surfactants and gives light enzyme exfoliation from papain. Beta-glucan, chia seed extract, and allantoin each have independent research supporting hydration or soothing, though that research mostly tested leave-on products rather than rinse-off cleansers. No independent clinical study of the finished product was found.', 'brand', 'Product claims are sourced from kieró; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"kieró":"https://us.kieroskincare.com/products/refining-enzyme-cleanser"},"ingredients":"Full INCI list per kieró: Zea Mays (Corn) Starch, Sodium Cocoyl Isethionate, Microcrystalline Cellulose, Sodium Methyl Cocoyl Taurate, Potassium Laurate, Sodium Lauroyl Glutamate, Allantoin, Maltodextrin, Papain, Water, CI 77499, Glycerin, Salvia Hispanica Seed Extract, 1,2-Hexanediol, Butylene Glycol, Beta-Glucan, Ethylhexylglycerin.","doctorOpinionShort":"A powder cleanser built on mild syndet surfactants (mainly sodium cocoyl isethionate, shown to be gentler on the skin barrier than soap) with papaya enzyme (papain) for light exfoliation. Beta-glucan, chia seed, and allantoin have real supporting research for hydration and soothing, though a rinse-off cleanser limits how much they do. Papain is a known allergen, so avoid it if you''re allergic to papaya, kiwi, or fig. No independent clinical study of this specific product was found.","doctorOpinionCitations":[{"url":"https://us.kieroskincare.com/products/refining-enzyme-cleanser","label":"kieroskincare.com: Refining Enzyme Cleanser — ingredient list and claims"},{"url":"https://www.aad.org/public/everyday-care/skin-care-secrets/routine/safely-exfoliate-at-home","label":"American Academy of Dermatology: How to safely exfoliate at home"}],"whoItsFor":["People who want gentle, daily enzyme exfoliation instead of a scrub or acid","Normal, oily, or combination skin looking for a cleanser that removes excess oil without a tight, stripped feeling","People who prefer a fragrance-free, vegan formula"],"howToUse":{"intro":"Per kieró''s own site: use daily as step 1 (cleanse) of the routine.","steps":["Pour a small amount of powder into wet hands.","Rub your hands together to create a creamy lather, then gently massage it into your skin.","Rinse well and pat your face dry.","Follow with moisturizer. The AAD recommends moisturizing right after any exfoliation."],"sourceUrl":"https://us.kieroskincare.com/products/refining-enzyme-cleanser","sourceLabel":"kieroskincare.com: Refining Enzyme Cleanser"},"warnings":["Allergy to papaya, papain, kiwi, or fig: avoid it or patch test first. Papain is a known allergen.","Using a prescription retinoid, retinol, or benzoyl peroxide: exfoliating on top of them can worsen dryness and irritation (AAD).","Don''t use on broken, cut, or sunburned skin.","Keep out of eyes. If you get redness, burning, or an allergic reaction, stop using it and see a doctor."],"ingredientScience":[{"name":"Papain (papaya enzyme)","text":"kieró states this gently exfoliates. Papain is a protease: in lab testing it broke down keratin and collagen, which mimics the skin''s natural shedding. A 2021 review found enzyme exfoliants do work but have been studied in only a handful of papers with few clinical trials. Papain is also a known allergen. It can loosen the proteins that hold skin cells together and has sensitized people through the skin.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/34897928/","label":"PubMed: An overview of the use of proteolytic enzymes as exfoliating agents"},{"url":"https://pubmed.ncbi.nlm.nih.gov/35892222/","label":"PubMed: In vitro effect on the proteolytic activity of papain with proteins of the skin as substrate"},{"url":"https://pubmed.ncbi.nlm.nih.gov/25705851/","label":"PubMed: Papain degrades tight junction proteins of human keratinocytes in vitro and sensitizes mice via the skin"}]},{"name":"Beta-glucan","text":"kieró states this hydrates and soothes. Topical beta-glucan increased skin hydration and reduced irritation in controlled studies. These include a split-face, double-blind, vehicle-controlled trial after laser treatment and a multicentre study in mild-to-moderate atopic dermatitis.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/33128496/","label":"PubMed: Skin care regimens containing β-glucan for skin recovery after fractional laser therapy — split-face, double-blinded, vehicle-controlled study"},{"url":"https://pubmed.ncbi.nlm.nih.gov/26654776/","label":"PubMed: β-Glucan-based cream in supportive treatment of mild-to-moderate atopic dermatitis"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12023766/","label":"NIH (PMC): Exploring the properties and application potential of β-glucan in skin care"}]},{"name":"Chia seed (Salvia hispanica) extract","text":"kieró states this reinforces the skin barrier. In a small 8-week study, a topical 4% chia seed oil formula improved skin hydration and barrier function (lower transepidermal water loss) in people with dry, itchy skin, with no adverse effects. That study tested a leave-on oil, not a rinse-off extract.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/20548903/","label":"PubMed: Effectiveness of topical chia seed oil on pruritus of end-stage renal disease patients and healthy volunteers"}]},{"name":"Sodium cocoyl isethionate","text":"The main cleansing agent. Lab and human studies show it is milder on the skin barrier than soap or sodium lauryl sulfate. Its micelles are too large to penetrate the skin''s outer layer as easily, which is why \"syndet\" cleansers are often recommended for dry or sensitive skin.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/17598025/","label":"PubMed: Why is sodium cocoyl isethionate (SCI) mild to the skin barrier?"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8954092/","label":"NIH (PMC): Skin cleansing without or with compromise — soaps and syndets"}]},{"name":"Allantoin","text":"A soothing, skin-protectant ingredient with mild keratolytic (dead-skin-loosening) and moisturizing effects, and a common ingredient in moisturizers for dermatitis-prone skin.","citations":[{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC11685320/","label":"NIH (PMC): The role of moisturizer containing anti-inflammatory ingredients on skin hydration in mild-moderate atopic dermatitis"}]}],"scientificCitations":[{"url":"https://www.aad.org/public/everyday-care/skin-care-secrets/routine/safely-exfoliate-at-home","text":"American Academy of Dermatology: How to safely exfoliate at home","summary":"AAD guidance: people with dry, sensitive, or acne-prone skin should choose gentle exfoliation, moisturize afterward, and avoid exfoliating on broken or sunburned skin or while using retinoids or benzoyl peroxide. This is general guidance, not product-specific validation."}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"website","url":"https://us.kieroskincare.com/products/refining-enzyme-cleanser","text":"kieroskincare.com: Refining Enzyme Cleanser customer reviews","summary":"kieró''s own product page shows 251 reviews, 93% of them five stars, mostly in Spanish (see the Community summary above)."},{"platform":"website","url":"https://skinsort.com/products/kiero/refining-enzyme-cleanser","text":"Skinsort: kieró Refining Enzyme Cleanser ingredient analysis","summary":"An independent ingredient-analysis site. It lists the formula as vegan, fungal-acne safe, and free of fragrance, harsh alcohols, parabens, silicones, and sulfates. This is an ingredient screen, not user reviews."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-kiero-airy-sun-stick-spf50', 'Airy Sun Stick SPF 50+', 'kieró', 'skincare', 'physical', 'A broad-spectrum SPF 50+ / PA++++ sunscreen stick with chamomile, vitamin E, and madecassoside (from centella). kieró positions it for daily UV protection with a lightweight, non-greasy finish that can be swiped on over makeup, and says it soothes and supports the skin barrier. It uses chemical (organic) UV filters, not zinc or titanium.', '$11.99 for 20 g (0.7 oz)', 'https://us.kieroskincare.com/cdn/shop/files/kiero-_-05_a549ac4a-c417-4be1-8731-03d3c0ffddb8.jpg', 'https://us.kieroskincare.com/products/sun-stick-spf-50', '["skin","spf","sunscreen","vegan"]'::jsonb, '["skin-hair"]'::jsonb, '["kieró"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"In the US, sunscreens are regulated as over-the-counter drugs. kieró doesn''t publish the percentage of each UV filter or say whether the product is water resistant. kieró states its products are vegan and cruelty-free; ayna did not independently verify that.","materials":"Solid silicone-and-wax stick (20 g / 0.7 oz). UV filters: avobenzone (UVA), octocrylene, homosalate, octisalate, and butyloctyl salicylate, all chemical filters with no zinc oxide or titanium dioxide. The soothing ingredients are chamomile flower water, sodium guaiazulene sulfonate (a chamomile-derived compound), madecassoside with other centella compounds, panthenol, and vitamin E. Plant oils include sunflower, avocado, soybean, shea, and annatto (Bixa orellana).","recalls":"No recalls found.","sideEffects":"Chemical UV filters can cause irritation or, rarely, allergic or photoallergic reactions; octocrylene is the most common culprit. The formula contains chamomile, so people allergic to ragweed or the daisy family should patch test first. Keep sticks away from the eyes. Full warnings are listed below.","opinionAlerts":"Safety note: a stick only reaches its labeled SPF if you apply enough, so swipe several passes over each area. It uses chemical UV filters, which FDA studies show are absorbed into the bloodstream. The FDA says that alone doesn''t mean they''re unsafe, and you should keep using sunscreen. Contains chamomile, so patch test if you''re allergic to ragweed or daisies. Soothing and barrier claims come from kieró, and no independent clinical study of the finished product was found."}'::jsonb, 'kieró positions this as a lightweight daily SPF 50+ / PA++++ stick. Its chamomile soothes, its vitamin E gives antioxidant defense, and its madecassoside strengthens the skin barrier, and it can be swiped over makeup, per the brand''s own site.

Daily broad-spectrum sunscreen is one of the best-supported habits in dermatology. In the Nambour randomized trial in Australia, adults assigned to daily sunscreen had about 24% less skin aging over 4.5 years. They also developed fewer squamous cell skin cancers and, in 10-year follow-up, half as many new melanomas as people who used sunscreen when they chose to. Those trials tested a basic SPF 15+ sunscreen, not this product, but the benefit comes from consistent daily use of any broad-spectrum sunscreen.

The main caveat with sticks is how much you apply. SPF is tested at 2 mg/cm², and studies show people typically apply a quarter to half of that, which cuts real-world protection roughly in proportion. Solid sticks make that easier to get wrong, so go over each area several times. The AAD also advises applying 15 minutes before going out and reapplying every two hours and after swimming or sweating. kieró doesn''t claim water resistance, so reapply after either.

The filters here (avobenzone, octocrylene, homosalate, octisalate) are all FDA-permitted. In a 2020 FDA randomized trial published in JAMA, all of them were absorbed into the bloodstream above the level at which the FDA waives further safety testing. The FDA and the study authors stressed that absorption doesn''t mean harm and that people should keep using sunscreen. Separately, a lab study found octocrylene can slowly break down into benzophenone as a product ages, so replace old or heat-exposed sunscreen. If either concern matters to you, a mineral (zinc oxide) sunscreen avoids both.

Madecassoside has real supporting research. It is the centella compound behind many "cica" products. In a 6-month double-blind study, a cream with madecassoside and vitamin C improved skin hydration, firmness, and fine wrinkles, and lab studies show it calms UV-triggered inflammation. Vitamin E is a well-documented skin antioxidant. No independent clinical study of this specific product was found.', 'kieró''s US site shows 657 customer reviews, and 593 of them (90%) are five stars; the rest are four stars. Most reviews are in Spanish and praise how easily it goes on, how fast it absorbs, and its non-greasy feel, including over makeup. For example: "No es grasoso y protege muy bien tu piel del sol" ("It''s not greasy and protects your skin from the sun really well"). These are reviews on the brand''s own site; no independent review data was found at time of writing.', 'Rated SPF 50+ / PA++++ broad spectrum, but real-world protection depends on applying enough, which is harder with a stick. Daily broad-spectrum sunscreen use has randomized-trial evidence for slowing skin aging and reducing squamous cell carcinoma and melanoma. Madecassoside, panthenol, and vitamin E add soothing and antioxidant support. No independent clinical study of the finished product was found.', 'brand', 'Product claims are sourced from kieró; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"kieró":"https://us.kieroskincare.com/products/sun-stick-spf-50"},"ingredients":"Full INCI list per kieró: Dimethicone, Synthetic Wax, Vinyl Dimethicone/Methicone Silsesquioxane Crosspolymer, Cetyl Ethylhexanoate, Octocrylene, Homosalate, Methyl Methacrylate Crosspolymer, Dibutyl Adipate, Butyloctyl Salicylate, Octisalate, Avobenzone, Pentylene Glycol, Polyglyceryl-4 Oleate, Helianthus Annuus (Sunflower) Seed Oil, Polyglyceryl-6 Oleate, Polyhydroxystearic Acid, Methylpropanediol, Persea Gratissima (Avocado) Oil, Ethylhexylglycerin, Caprylyl Glycol, Glycine Soja (Soybean) Oil, Tocopherol, Steareth-30, Lactobacillus Ferment Lysate, Butyrospermum Parkii (Shea) Butter Extract, Bixa Orellana Seed Oil, Water, Sodium Guaiazulene Sulfonate, Panthenol, Butylene Glycol, 1,2-Hexanediol, Anthemis Nobilis Flower Water, Madecassoside, Asiaticoside, Asiatic Acid, Madecassic Acid.","doctorOpinionShort":"Daily broad-spectrum sunscreen has strong randomized-trial evidence for slowing skin aging and lowering skin-cancer risk. The catch with any stick is applying enough, so use several passes per area and reapply every two hours. It uses chemical filters, which FDA studies show are absorbed into the blood (not proven harmful; a mineral sunscreen is the alternative if that concerns you). Madecassoside and vitamin E have real supporting research. No independent clinical study of this specific product was found.","doctorOpinionCitations":[{"url":"https://us.kieroskincare.com/products/sun-stick-spf-50","label":"kieroskincare.com: Airy Sun Stick SPF 50+ — ingredient list and claims"},{"url":"https://www.aad.org/public/everyday-care/sun-protection/shade-clothing-sunscreen/how-to-apply-sunscreen","label":"American Academy of Dermatology: How to apply sunscreen"},{"url":"https://www.fda.gov/drugs/understanding-over-counter-medicines/sunscreen-how-help-protect-your-skin-sun","label":"FDA: Sunscreen — how to help protect your skin from the sun"}],"whoItsFor":["People who want a mess-free daily SPF they can reapply over makeup","Oily or combination skin looking for a non-greasy finish","Touch-ups on the face, ears, nose, and around the eyes during the day"],"howToUse":{"intro":"Per kieró''s own site: swipe the stick on as the last step of your morning routine, or over makeup, evenly covering all sun-exposed areas. Reapply through the day as needed.","steps":["Go over each area several times (back and forth). A single light swipe won''t deliver the labeled SPF.","Apply about 15 minutes before going outside (AAD).","Reapply at least every two hours, and right after swimming or sweating (AAD / FDA)."],"sourceUrl":"https://us.kieroskincare.com/products/sun-stick-spf-50","sourceLabel":"kieroskincare.com: Airy Sun Stick SPF 50+"},"warnings":["Allergy to ragweed, chamomile, or the daisy family: patch test first.","For external use only. Keep it out of the eyes, and don''t use it on broken or damaged skin.","Rash, irritation, or a reaction after sun exposure: stop using it and see a doctor. Octocrylene can cause photoallergic reactions.","Not stated as water resistant: reapply after swimming or sweating.","Children under 6 months: ask a doctor before using any sunscreen (FDA)."],"ingredientScience":[{"name":"Daily broad-spectrum sunscreen","text":"In the Nambour randomized trial, adults assigned to daily sunscreen had no detectable increase in skin aging over 4.5 years, 24% less than the comparison group. In 10-year follow-up, they had half as many new melanomas (11 vs 22), with a larger drop in invasive melanoma.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/23732711/","label":"PubMed: Sunscreen and prevention of skin aging — a randomized trial (Hughes et al., Ann Intern Med 2013)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/21135266/","label":"PubMed: Reduced melanoma after regular sunscreen use — randomized trial follow-up (Green et al., J Clin Oncol 2011)"}]},{"name":"How much you apply","text":"SPF is measured at 2 mg/cm². People typically apply 0.5–1 mg/cm², and actual SPF falls roughly in proportion to the amount applied. That is why you should use several passes with a stick.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/19614894/","label":"PubMed: The influence of the amount of sunscreen applied on its sun protection factor"},{"url":"https://pubmed.ncbi.nlm.nih.gov/22463921/","label":"PubMed: High-SPF sunscreens may compensate for lower user application amounts"}]},{"name":"Chemical UV filters (avobenzone, octocrylene, homosalate, octisalate)","text":"In a 2020 FDA randomized trial, all of these filters were absorbed into the bloodstream after application, above the level at which the FDA waives further safety testing. The authors stressed that this doesn''t mean they are unsafe and that people shouldn''t stop using sunscreen. Separately, a lab study found benzophenone in every octocrylene-containing sunscreen tested, rising as products aged.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/31961417/","label":"PubMed: Effect of sunscreen application on plasma concentration of sunscreen active ingredients — a randomized clinical trial (JAMA 2020)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/33763894/","label":"PubMed: The presence of benzophenone in sunscreens and cosmetics containing the organic UV filter octocrylene"}]},{"name":"Madecassoside (centella)","text":"kieró states this strengthens the skin barrier. In a 6-month randomized, double-blind study, topical madecassoside with vitamin C improved hydration, firmness, and wrinkles in photoaged skin. Lab studies show madecassoside dampens UV-triggered inflammation.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/18503551/","label":"PubMed: Long-term effects of topical ascorbic acid and madecassoside in photoaged human skin"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6290557/","label":"NIH (PMC): Madecassoside inhibits melanin synthesis by blocking ultraviolet-induced inflammation"}]},{"name":"Vitamin E","text":"kieró states this gives antioxidant defense. Vitamin E is one of skin''s main fat-soluble antioxidants and helps protect it from oxidative and UV-related stress. It can occasionally cause contact dermatitis.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/12239421/","label":"PubMed: Antioxidants and the Response of Skin to Oxidative Stress — Vitamin E as a Key Indicator"}]}],"scientificCitations":[{"url":"https://www.aad.org/public/everyday-care/sun-protection/shade-clothing-sunscreen/how-to-apply-sunscreen","text":"American Academy of Dermatology: How to apply sunscreen","summary":"AAD guidance: use SPF 30+ broad-spectrum sunscreen, apply about 15 minutes before going out, and reapply every two hours and after swimming or sweating. This is general guidance, not product-specific validation."},{"url":"https://www.fda.gov/drugs/understanding-over-counter-medicines/sunscreen-how-help-protect-your-skin-sun","text":"FDA: Sunscreen — how to help protect your skin from the sun","summary":"FDA consumer guidance on broad-spectrum SPF, reapplication, and sunscreen use in infants under 6 months."}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"website","url":"https://us.kieroskincare.com/products/sun-stick-spf-50","text":"kieroskincare.com: Airy Sun Stick SPF 50+ customer reviews","summary":"kieró''s own product page shows 657 reviews, 90% of them five stars and the rest four stars, mostly in Spanish (see the Community summary above)."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb)
on conflict (id) do update set
    name = excluded.name,
    brand = excluded.brand,
    category = excluded.category,
    product_type = excluded.product_type,
    summary = excluded.summary,
    price = excluded.price,
    image = excluded.image,
    url = excluded.url,
    tags = excluded.tags,
    health_functions = excluded.health_functions,
    where_to_buy = excluded.where_to_buy,
    where_to_buy_in_stock = excluded.where_to_buy_in_stock,
    safety = excluded.safety,
    doctor_opinion = excluded.doctor_opinion,
    community_review = excluded.community_review,
    effectiveness = excluded.effectiveness,
    clinician_opinion_source = excluded.clinician_opinion_source,
    clinician_attribution = excluded.clinician_attribution,
    source = excluded.source,
    internal = excluded.internal,
    requires_prescription = excluded.requires_prescription,
    user_rating = excluded.user_rating,
    is_active = excluded.is_active,
    extra = excluded.extra;

update public.product_catalog
set safety = safety - 'opinionAlerts'
where id = 'p-lola-pad';
